Generated Query:
PREFIX ins: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber ?premiumAmount
       (COUNT(DISTINCT ?claim) AS ?numberOfClaims)
       (SUM(?lossComponent) AS ?totalLoss)
       ((SUM(?lossComponent) / xsd:decimal(?premiumAmount)) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:against ?pcd .

    ?pcd ins:hasPolicy ?policy ;
         ins:hasPremiumAmount ?premium .

    ?policy ins:policyNumber ?policyNumber .
    ?premium ins:premiumAmount ?premiumAmount .

    {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
  }
}
GROUP BY ?policyNumber ?premiumAmount
ORDER BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyHolder (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy ins:hasPolicyHolder ?policyHolder ;
            ins:policyNumber ?policyNumber .
    ?coverage ins:hasPolicy ?policy ;
              ins:hasPremiumAmount ?premium .
    ?premium ins:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolder

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:soldByAgent ?agent .
    ?agent ins:agentId ?agentId .
  }
}
GROUP BY ?agentId
ORDER BY ?agentId

PREFIX ins: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber ?openDate ?closeDate
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber .
    OPTIONAL { ?claim ins:claimOpenDate ?openDate . }
    OPTIONAL { ?claim ins:claimCloseDate ?closeDate . }
  }
}
ORDER BY ?claimNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber
       (COALESCE(SUM(DISTINCT ?lossPaymentAmount), 0) +
        COALESCE(SUM(DISTINCT ?lossReserveAmount), 0) +
        COALESCE(SUM(DISTINCT ?expensePaymentAmount), 0) +
        COALESCE(SUM(DISTINCT ?expenseReserveAmount), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber
